import React from "react";

export default function EventData() {
    const n1 = 20;
    const n2 = 4;

    const handleButtonClick = (ev) => {
        let t = ev.target.innerText
        let s = (t === 'start') ? 'stop' : 'start'
        ev.target.innerText = s
        alert(`You clicked ${t}`)
    }
    const onclick = (ev) => {
        let t = ev.target.innerText
        let s = (t === 'start') ? 'stop' : 'start'
        ev.target.innerText = s
        alert(`You clicked ${t}`)
    }

    return (
        <div style={{ textAlign: 'center', marginTop:20 }}>
            <button onclick={(ev) => onClickStartStop(ev)}>start</button><br/><br/>
            <button onClick={(ev) => handleButtonClick(ev)}>start</button><br/><br/>
            <button onClick={(ev) => handleButtonClick(ev)}>30*40</button><br/><br/>
        </div>
    )
}
